19	async fn run_tui() -> anyhow::Result<()> {
20	    use std::io;
21	    use std::time::Duration;
22	
23	    use crossterm::{
24	        event::{DisableMouseCapture, EnableMouseCapture},
25	        execute,
26	        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
27	    };
28	    use ratatui::backend::CrosstermBackend;
29	    use ratatui::Terminal;
30	
31	    // Terminal setup
32	    enable_raw_mode()?;
33	    let mut stdout = io::stdout();
34	    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
35	    let backend = CrosstermBackend::new(stdout);
36	    let mut terminal = Terminal::new(backend)?;
37	
38	    // App init
39	    let mut app = app::App::new();
40	    app.log(app::LogLevel::Info, format!("rmpca v{} started", env!("CARGO_PKG_VERSION")));
41	    app.log(
42	        app::LogLevel::Info,
43	        "Ready — select a workflow step to begin",
44	    );
45	
46	    // Main loop
47	    let tick_rate = Duration::from_millis(100);
48	    while app.running {
49	        terminal.draw(|f| ui::draw(f, &app))?;
50	
51	        if let Some(ev) = event::poll_event(tick_rate)? {
52	            event::handle_event(&mut app, ev).await?;
53	        }
54	    }
55	
56	    // Terminal teardown
57	    disable_raw_mode()?;
58	    execute!(
59	        terminal.backend_mut(),
60	        LeaveAlternateScreen,
61	        DisableMouseCapture
62	    )?;
63	    terminal.show_cursor()?;
64	
65	    Ok(())
66	}

