 57	pub struct FileBrowser {
 58	    pub current_path: PathBuf,
 59	    pub entries: Vec<FileEntry>,
 60	    pub selection: usize,
 61	    pub filter: FileFilter,
 62	    pub target_field: InputField,
 63	    pub show_hidden: bool,
 64	    pub previous_view: View,
 65	}
