449	    pub fn close_file_browser(&mut self, selected_path: Option<PathBuf>) {
450	        let previous_view = self
451	            .file_browser
452	            .as_ref()
453	            .map(|b| b.previous_view.clone())
454	            .unwrap_or(View::Home);
455	
456	        if let Some(path) = selected_path {
457	            let path_str = path.to_string_lossy().to_string();
458	
459	            if let Some(browser) = &self.file_browser {
460	                match browser.target_field {
461	                    InputField::InputFile => {
462	                        self.input_file = Some(path_str.clone());
463	                        if self.output_file.is_none() {
464	                            let out = path_str
465	                                .replace(".geojson", ".rmp")
466	                                .replace(".json", ".rmp");
467	                            self.output_file = Some(out);
468	                        }
469	                        self.log(
470	                            LogLevel::Success,
471	                            format!("Input file selected: {}", path_str),
472	                        );
473	                        self.current_view = View::Compile;
474	                    }
475	                    InputField::OutputFile => {
476	                        self.output_file = Some(path_str.clone());
477	                        self.log(
478	                            LogLevel::Success,
479	                            format!("Output file selected: {}", path_str),
480	                        );
481	                        self.current_view = View::Compile;
482	                    }
483	                    InputField::CacheFile => {
484	                        self.cache_file = Some(path_str.clone());
485	                        self.log(
486	                            LogLevel::Success,
487	                            format!("Cache file selected: {}", path_str),
