 92	/// Predict hyperparameters for a given instance.
 93	///
 94	/// Tries to load the neural model. If missing or failed, falls back to
 95	/// sensible defaults.
 96	pub fn predict_hyperparams(features: &InstanceFeatures) -> SolverHyperparams {
 97	    let path = default_model_path();
 98	    if path.exists() {
 99	        match HyperparamPredictor::from_file(&path) {
100	            Ok(model) => {
101	                match model.predict(features) {
102	                    Ok(params) => return params,
103	                    Err(e) => {
104	                        tracing::warn!("Hyperparam predictor inference failed: {}. Falling back to defaults.", e);
105	                    }
106	                }
107	            }
108	            Err(e) => {
109	                tracing::warn!("Failed to load hyperparam predictor: {}. Falling back to defaults.", e);
110	            }
111	        }
112	    }
113	    SolverHyperparams::default_fallback()
114	}
