1214	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1215	    let stops_val = args
1216	        .get("stops")
1217	        .and_then(|v| v.as_array())
1218	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1219	
1220	    if stops_val.is_empty() {
1221	        anyhow::bail!("At least one stop (the depot) is required");
1222	    }
1223	
1224	    let stops: Vec<VRPSolverStop> = stops_val
1225	        .iter()
1226	        .enumerate()
1227	        .map(|(i, s)| {
1228	            let lat = s.get("lat").and_then(|v| v.as_f64())
1229	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1230	            let lon = s.get("lon").and_then(|v| v.as_f64())
1231	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lon'", i))?;
1232	            let label = s.get("label").and_then(|v| v.as_str())
1233	                .unwrap_or_else(|| "")
1234	                .to_string();
1235	            let demand = s.get("demand").and_then(|v| v.as_f64());
1236	            Ok(VRPSolverStop {
1237	                lat,
1238	                lon,
1239	                label: if label.is_empty() { format!("Stop {}", i) } else { label },
1240	                demand,
1241	                arrival_time: None,
1242	            })
1243	        })
1244	        .collect::<Result<Vec<_>>>()?;
1245	
1246	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1247	    let vehicle_capacity = args.get("vehicle_capacity").and_then(|v| v.as_f64()).unwrap_or(100.0);
1248	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("default").to_string();
1249	    let avg_speed_kmh = args.get("avg_speed_kmh").and_then(|v| v.as_f64()).unwrap_or(40.0);
1250	    let objective = match args.get("objective").and_then(|v| v.as_str()).unwrap_or("min_distance") {
1251	        "min_time" => VrpObjective::MinTime,
1252	        "balance_load" => VrpObjective::BalanceLoad,
1253	        "min_vehicles" => VrpObjective::MinVehicles,
1254	        _ => VrpObjective::MinDistance,
1255	    };
1256	
1257	    // Build haversine distance matrix
1258	    let matrix = build_haversine_matrix(&stops, avg_speed_kmh);
1259	
1260	    #[cfg(feature = "ml")]
1261	    let mut input = VRPSolverInput {
1262	        locations: stops,
1263	        num_vehicles,
1264	        vehicle_capacity,
1265	        objective,
1266	        matrix: Some(matrix),
1267	        service_time_secs: None,
1268	        use_time_windows: false,
1269	        window_open: None,
1270	        window_close: None,
1271	        hyperparams: None,
1272	    };
1273	
1274	    #[cfg(not(feature = "ml"))]
1275	    let input = VRPSolverInput {
1276	        locations: stops,
1277	        num_vehicles,
1278	        vehicle_capacity,
1279	        objective,
1280	        matrix: Some(matrix),
1281	        service_time_secs: None,
1282	        use_time_windows: false,
1283	        window_open: None,
1284	        window_close: None,
1285	        hyperparams: None,
1286	    };
1287	
1288	    // AutoML: predict best hyperparameters for this instance
1289	    #[cfg(feature = "ml")]
1290	    let automl_used = {
1291	        let features = InstanceFeatures::from_input(&input);
1292	        let params = predict_hyperparams(&features);
1293	        let used = params.model_used;
1294	        input.hyperparams = Some(params);
1295	        used
1296	    };
1297	    #[cfg(not(feature = "ml"))]
1298	    let automl_used = false;
1299	
1300	    tracing::info!("vrp_solve: {} stops, {} vehicles, solver={}, AutoML={}", 
1301	        input.locations.len(), num_vehicles, solver_id, automl_used);
1302	
1303	    let output = solve_with(&solver_id, &input).await
1304	        .map_err(|e| anyhow::anyhow!("VRP solver failed: {}", e))?;
1305	
1306	    // Convert routes to JSON
1307	    let routes_json: Vec<Value> = output.routes.iter().flatten().enumerate().map(|(vi, route)| {
1308	        let stops_json: Vec<Value> = route.iter().map(|s| {
1309	            json!({
1310	                "lat": s.lat,
1311	                "lon": s.lon,
1312	                "label": s.label,
1313	                "demand": s.demand,
1314	            })
1315	        }).collect();
1316	        json!({
1317	            "vehicle": vi,
1318	            "stops": stops_json,
1319	        })
1320	    }).collect();
1321	
1322	    Ok(json!({
1323	        "total_distance_km": output.total_distance_km,
1324	        "total_time_min": output.total_time_min,
1325	        "routes": routes_json,
1326	        "unassigned": output.unassigned,
1327	    }))
1328	}
