1346	        .iter()
1347	        .enumerate()
1348	        .map(|(i, p)| {
1349	            let lon = p.get("lon").and_then(|v| v.as_f64())
1350	                .ok_or_else(|| anyhow::anyhow!("Point {} missing 'lon'", i))?;
