1352	                .ok_or_else(|| anyhow::anyhow!("Point {} missing 'lat'", i))?;
1353	            Ok((lon, lat))
1354	        })
1355	        .collect::<Result<Vec<_>>>()?;
1356	
1357	    let elevations = dem.get_elevations(&points)
1358	        .map_err(|e| anyhow::anyhow!("Elevation query failed: {}", e))?;
1359	
1360	    let results: Vec<Value> = points.iter().zip(elevations.iter()).enumerate().map(|(i, ((lon, lat), elev))| {
