20	/// Haversine distance in meters between two WGS-84 points (lat, lon order).
21	pub fn haversine_m(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
22	    const R: f64 = 6_371_000.0;
23	    let dlat = (lat2 - lat1).to_radians();
24	    let dlon = (lon2 - lon1).to_radians();
25	    let a = (dlat / 2.0).sin().powi(2)
26	        + lat1.to_radians().cos() * lat2.to_radians().cos() * (dlon / 2.0).sin().powi(2);
27	    R * 2.0 * a.sqrt().atan2((1.0 - a).sqrt())
28	}

