718	                    self.browse_selection = (self.browse_selection + max - 1) % max;
719	                }
720	            }
721	            View::BrowseRoutes => {
722	                let max = self.saved_routes.len().max(1);
723	                if max > 0 {
724	                    self.browse_selection = (self.browse_selection + max - 1) % max;
725	                }
726	            }
727	            _ => {}
728	        }
729	    }
