731	    pub fn navigate_down(&mut self) {
732	        match self.current_view {
733	            View::Home => {
734	                self.workflow_selection = (self.workflow_selection + 1) % 7;
735	            }
736	            View::BrowseMaps => {
737	                let max = self.cached_maps.len().max(1);
738	                if max > 0 {
739	                    self.browse_selection = (self.browse_selection + 1) % max;
