 67	    // 1. Try relative to current executable
 68	    if let Ok(exe_path) = std::env::current_exe() {
 69	        if let Some(exe_dir) = exe_path.parent() {
 70	            let p = exe_dir.join("models").join("automl.safetensors");
 71	            if p.exists() {
 72	                return p;
 73	            }
 74	        }
 75	    }
 76	
 77	    // 2. Try relative to current working directory
 78	    let p = std::path::PathBuf::from("models/automl.safetensors");
 79	    if p.exists() {
 80	        return p;
 81	    }
 82	
 83	    // Fallback to exe-relative path anyway (for creation/error reporting)
 84	    std::env::current_exe()
 85	        .unwrap_or_else(|_| std::path::PathBuf::from("."))
 86	        .parent()
 87	        .unwrap_or(std::path::Path::new("."))
 88	        .join("models")
 89	        .join("automl.safetensors")
 90	}
