 21	//! Dynamic solver registry: built-ins first, then dynamically registered solvers.
 22	
 23	use super::solvers::clarke_wright::ClarkeWrightSolver;
 24	use super::solvers::default::DefaultSolver;
 25	use super::solvers::neural_guided::NeuralGuidedSolver;
 26	use super::solvers::or_opt::OrOptSolver;
 27	use super::solvers::sweep::SweepSolver;
 28	use super::solvers::two_opt::TwoOptSolver;
 29	use super::types::{VRPSolver, VRPSolverInput, VRPSolverOutput};
 30	use std::collections::HashMap;
 31	use std::sync::{Arc, OnceLock, RwLock};
 32	
 33	static REGISTRY: OnceLock<RwLock<SolverRegistryInner>> = OnceLock::new();
 34	
 35	fn registry() -> &'static RwLock<SolverRegistryInner> {
 36	    REGISTRY.get_or_init(|| RwLock::new(SolverRegistryInner::new()))
 37	}
 38	
 39	struct SolverRegistryInner {
 40	    solvers: HashMap<String, Arc<dyn VRPSolver>>,
 41	    builtin_ids: Vec<String>,
 42	    dynamic_order: Vec<String>,
 43	}
 44	
 45	impl SolverRegistryInner {
 46	    fn new() -> Self {
 47	        let builtins: Vec<Arc<dyn VRPSolver>> = vec![
 48	            Arc::new(ClarkeWrightSolver),
 49	            Arc::new(SweepSolver),
 50	            Arc::new(OrOptSolver),
 51	            Arc::new(TwoOptSolver),
 52	            Arc::new(NeuralGuidedSolver),
 53	            Arc::new(DefaultSolver),
 54	        ];
 55	        let builtin_ids: Vec<String> = builtins.iter().map(|s| s.id().to_string()).collect();
 56	        let mut solvers = HashMap::new();
 57	        for s in builtins {
 58	            let id = s.id().to_string();
 59	            solvers.insert(id, s);
 60	        }
 61	        Self {
 62	            solvers,
 63	            builtin_ids,
 64	            dynamic_order: Vec::new(),
 65	        }
 66	    }
 67	}
 68	
 69	/// Register a custom solver. If the id already exists, it is replaced.
 70	pub fn register_solver(solver: Arc<dyn VRPSolver>) {
 71	    let id = solver.id().to_string();
 72	    let mut reg = registry().write().unwrap();
 73	    let had = reg.solvers.contains_key(&id);
 74	    reg.solvers.insert(id.clone(), solver);
 75	    if !had && !reg.builtin_ids.contains(&id) {
 76	        reg.dynamic_order.push(id);
 77	    }
 78	}
 79	
 80	/// Unregister a solver by id. Built-in solver ids are ignored.
 81	/// Returns true if a dynamic solver was removed.
 82	pub fn unregister_solver(id: &str) -> bool {
 83	    let mut reg = registry().write().unwrap();
 84	    if reg.builtin_ids.contains(&id.to_string()) {
 85	        return false;
 86	    }
 87	    let removed = reg.solvers.remove(id).is_some();
 88	    if removed {
 89	        reg.dynamic_order.retain(|x| x != id);
 90	    }
 91	    removed
 92	}
 93	
 94	/// Return the ordered list of solvers: built-ins first, then dynamically registered.
 95	pub fn get_solver_list() -> Vec<String> {
 96	    let reg = registry().read().unwrap();
 97	    let mut ids: Vec<String> = reg.builtin_ids.clone();
 98	    for id in &reg.dynamic_order {
 99	        if reg.solvers.contains_key(id) {
100	            ids.push(id.clone());
101	        }
102	    }
103	    ids
104	}
105	
106	/// Solve using a solver by id. Falls back to default.
107	pub async fn solve_with(id: &str, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
108	    // Clone the Arc out before .await so we don't hold RwLockReadGuard across await.
109	    let solver: Arc<dyn VRPSolver> = {
110	        let reg = registry().read().unwrap();
111	        match reg.solvers.get(id).or_else(|| reg.solvers.get("default")) {
112	            Some(s) => Arc::clone(s),
113	            None => return Err(format!("Solver '{id}' not found and no default available")),
114	        }
115	    };
116	    solver.solve(input).await
117	}
