17	#[tokio::test]
18	async fn benchmark_neural_vs_2opt() {
19	    // Generate a non-trivial problem: 50 stops in a grid
20	    let mut stops = vec![make_stop(0.0, 0.0, "depot")];
21	    for x in 0..7 {
22	        for y in 0..7 {
23	            if x == 0 && y == 0 { continue; }
24	            stops.push(make_stop(x as f64 * 0.1, y as f64 * 0.1, &format!("stop_{}_{}", x, y)));
25	        }
26	    }
27	
28	    let matrix = build_haversine_matrix(&stops, 40.0);
29	    let input = VRPSolverInput {
30	        locations: stops.clone(),
31	        num_vehicles: 3,
32	        vehicle_capacity: 100.0,
33	        objective: VrpObjective::MinDistance,
34	        matrix: Some(matrix),
35	        service_time_secs: None,
36	        use_time_windows: false,
37	        window_open: None,
38	        window_close: None,
39	        hyperparams: None,
40	    };
41	
42	    println!("Benchmarking NeuralGuidedSolver vs TwoOptSolver (50 stops, 3 vehicles)");
43	
44	    let solver_2opt = TwoOptSolver;
45	    let start = Instant::now();
46	    let out_2opt = solver_2opt.solve(&input).await.unwrap();
47	    let duration_2opt = start.elapsed();
48	    println!("TwoOptSolver: dist = {}, time = {:?}", out_2opt.total_distance_km, duration_2opt);
49	
50	    let solver_neural = NeuralGuidedSolver;
51	    let start = Instant::now();
52	    let out_neural = solver_neural.solve(&input).await.unwrap();
53	    let duration_neural = start.elapsed();
54	    println!("NeuralGuidedSolver: dist = {}, time = {:?}", out_neural.total_distance_km, duration_neural);
55	    
56	    let dist_2opt: f64 = out_2opt.total_distance_km.parse().unwrap();
57	    let dist_neural: f64 = out_neural.total_distance_km.parse().unwrap();
58	    
59	    if dist_neural < dist_2opt {
60	        println!("NeuralGuidedSolver improved result by {:.2}%", (dist_2opt - dist_neural) / dist_2opt * 100.0);
61	    } else if dist_neural > dist_2opt {
62	        println!("NeuralGuidedSolver was {:.2}% worse than 2-Opt", (dist_neural - dist_2opt) / dist_2opt * 100.0);
63	    } else {
64	        println!("Both solvers produced the same distance.");
65	    }
66	}

  1	//! Default fallback solver: zone-clustering + nearest-neighbor + 2-opt improvement.
  2	
  3	use super::super::types::*;
  4	use super::super::utils::{
  5	    cluster_by_zones, matrix_get_dist, matrix_get_time, nearest_neighbor_route,
  6	    order_clusters_by_start, two_opt_improve,
  7	};
  8	
  9	pub struct DefaultSolver;
 10	
 11	#[async_trait::async_trait]
 12	impl VRPSolver for DefaultSolver {
 13	    fn id(&self) -> &str {
 14	        "default"
 15	    }
 16	    fn label(&self) -> &str {
 17	        "Default (Zone-cluster + 2-Opt)"
 18	    }
 19	    fn requires_matrix(&self) -> bool {
 20	        true
 21	    }
 22	
 23	    async fn solve(&self, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
 24	        let matrix = input
 25	            .matrix
 26	            .as_ref()
 27	            .ok_or("Default solver requires a distance matrix")?;
 28	        let n = input.locations.len();
 29	
 30	        let num_zones = ((n as f64).sqrt().ceil() as usize).clamp(2, 6);
 31	        let clusters = cluster_by_zones(&input.locations, num_zones);
 32	        let ordered_clusters = order_clusters_by_start(&clusters, &input.locations, 0);
 33	
 34	        let mut route_indices: Vec<usize> = Vec::new();
 35	        for cluster in &ordered_clusters {
 36	            let start_in_cluster = cluster.iter().position(|&i| i == 0);
 37	            let start_idx = start_in_cluster.unwrap_or(0);
 38	            let segment = nearest_neighbor_route(matrix, cluster, start_idx);
 39	            route_indices.extend(segment);
 40	        }
 41	
 42	        let mut with_return = route_indices;
 43	        with_return.push(0);
 44	
 45	        let max_iter = input.hyperparams.as_ref().map(|p| p.max_iterations).unwrap_or(300);
 46	        let improved = two_opt_improve(matrix, &with_return, max_iter);
 47	
 48	        let mut total_dist = 0.0;
 49	        let mut total_time = 0.0;
 50	        for i in 0..improved.len() - 1 {
 51	            total_dist += matrix_get_dist(matrix, improved[i], improved[i + 1]);
 52	            total_time += matrix_get_time(matrix, improved[i], improved[i + 1]);
 53	        }
 54	
 55	        let result = crate::core::vrp::types::SolveResult {
 56	            routes: vec![improved],
 57	            total_distance: total_dist,
 58	            total_time,
 59	        };
 60	        
 61	        Ok(result.into_output(input))
 62	    }
 63	    fn clone_box(&self) -> Box<dyn VRPSolver> {
 64	        Box::new(DefaultSolver)
 65	    }
 66	}
