252	
253	    if items.is_empty() {
254	        return;
255	    }
256	
257	    let list_items: Vec<ratatui::widgets::ListItem> = items
258	        .iter()
259	        .enumerate()
260	        .map(|(i, name)| {
261	            let style = if i == selection {
262	                ratatui::style::Style::default()
263	                    .fg(ratatui::style::Color::Yellow)
264	                    .add_modifier(ratatui::style::Modifier::BOLD)
265	            } else {
266	                ratatui::style::Style::default().fg(ratatui::style::Color::White)
267	            };
268	            let prefix = if i == selection { " > " } else { "   " };
269	            ratatui::widgets::ListItem::new(ratatui::text::Span::styled(
270	                format!("{}{}", prefix, name),
271	                style,
272	            ))
273	        })
274	        .collect();
275	
276	    let list = ratatui::widgets::List::new(list_items);
277	    f.render_widget(list, inner);
