  75	
  76	fn send(id: &Value, result: Value) {
  77	    let out = json!({
  78	        "jsonrpc": "2.0",
  79	        "id": id,
  80	        "result": result
  81	    });
  82	    let mut stdout = std::io::stdout().lock();
  83	    let _ = writeln!(stdout, "{out}");
  84	    let _ = stdout.flush();
  85	}
  86	
  87	fn send_err(id: &Value, code: i64, msg: &str) {
  88	    let out = json!({
  89	        "jsonrpc": "2.0",
  90	        "id": id,
  91	        "error": { "code": code, "message": msg }
  92	    });
  93	    let mut stdout = std::io::stdout().lock();
  94	    let _ = writeln!(stdout, "{out}");
  95	    let _ = stdout.flush();
  96	}
  97	
  98	fn tool_success(id: &Value, result: &Result<Value>) {
  99	    match result {
 100	        Ok(val) => send(
 101	            id,
 102	            json!({
 103	                "content": [{
 104	                    "type": "text",
 105	                    "text": serde_json::to_string_pretty(val).unwrap_or_default()
 106	                }]
 107	            }),
 108	        ),
 109	        Err(e) => send(
 110	            id,
 111	            json!({
 112	                "content": [{
 113	                    "type": "text",
 114	                    "text": format!("Error: {e:#}")
 115	                }],
 116	                "isError": true
 117	            }),
 118	        ),
 119	    }
 120	}
