 911	fn parse_bbox(args: &Value) -> anyhow::Result<BBoxRequest> {
 912	    let bbox = args
 913	        .get("bbox")
 914	        .ok_or_else(|| anyhow::anyhow!("Missing 'bbox' parameter"))?;
 915	    Ok(BBoxRequest {
 916	        min_lon: bbox
 917	            .get("min_lon")
 918	            .and_then(|v| v.as_f64())
 919	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lon required"))?,
 920	        min_lat: bbox
 921	            .get("min_lat")
 922	            .and_then(|v| v.as_f64())
 923	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lat required"))?,
 924	        max_lon: bbox
 925	            .get("max_lon")
 926	            .and_then(|v| v.as_f64())
 927	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lon required"))?,
 928	        max_lat: bbox
 929	            .get("max_lat")
 930	            .and_then(|v| v.as_f64())
 931	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lat required"))?,
 932	    })
 933	}
 934	
 935	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 936	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 937	        return RoadClass::all_vehicle();
 938	    };
 939	    if arr.is_empty() {
 940	        return RoadClass::all_vehicle();
 941	    }
 942	    arr.iter()
 943	        .filter_map(|v| v.as_str())
 944	        .filter_map(|s| match s {
 945	            "residential" => Some(RoadClass::Residential),
 946	            "tertiary" => Some(RoadClass::Tertiary),
 947	            "secondary" => Some(RoadClass::Secondary),
 948	            "primary" => Some(RoadClass::Primary),
 949	            "trunk" => Some(RoadClass::Trunk),
 950	            "motorway" => Some(RoadClass::Motorway),
 951	            "unclassified" => Some(RoadClass::Unclassified),
 952	            "living_street" => Some(RoadClass::LivingStreet),
 953	            "service" => Some(RoadClass::Service),
 954	            "secondary_link" => Some(RoadClass::SecondaryLink),
 955	            "primary_link" => Some(RoadClass::PrimaryLink),
 956	            "trunk_link" => Some(RoadClass::TrunkLink),
 957	            "motorway_link" => Some(RoadClass::MotorwayLink),
 958	            _ => None,
 959	        })
 960	        .collect()
 961	}
 962	
 963	fn parse_oneway_mode(args: &Value) -> OnewayMode {
 964	    match args
 965	        .get("oneway_mode")
 966	        .and_then(|v| v.as_str())
 967	        .unwrap_or("respect")
 968	    {
 969	        "ignore" => OnewayMode::Ignore,
 970	        "reverse" => OnewayMode::Reverse,
 971	        _ => OnewayMode::Respect,
 972	    }
 973	}
 974	
 975	fn parse_solver_mode(args: &Value) -> SolverMode {
 976	    match args
 977	        .get("mode")
 978	        .and_then(|v| v.as_str())
 979	        .unwrap_or("cpp")
 980	    {
 981	        "vrp" => SolverMode::Vrp,
 982	        _ => SolverMode::Cpp,
 983	    }
 984	}
