 988	async fn handle_extract_overture(args: &Value) -> Result<Value> {
 989	    let bbox = parse_bbox(args)?;
 990	    let road_classes = parse_road_classes(args);
 991	    let output_path = args
 992	        .get("output_path")
 993	        .and_then(|v| v.as_str())
 994	        .unwrap_or("extract-output.geojson")
 995	        .to_string();
 996	
 997	    tracing::info!("extract_overture: bbox={:.4},{:.4},{:.4},{:.4}",
 998	        bbox.min_lon, bbox.min_lat, bbox.max_lon, bbox.max_lat);
