1545	
1546	fn handle_fuel_estimate(args: &Value) -> Result<Value> {
1547	    let samples_val = args
1548	        .get("samples")
1549	        .and_then(|v| v.as_array())
1550	        .ok_or_else(|| anyhow::anyhow!("Missing 'samples' parameter"))?;
1551	
1552	    if samples_val.len() < 2 {
1553	        anyhow::bail!("At least 2 samples are required for fuel estimation");
1554	    }
1555	
1556	    let base_consumption = args
1557	        .get("base_consumption")
1558	        .and_then(|v| v.as_f64())
1559	        .unwrap_or(0.08);
1560	
1561	    // Build an ElevationProfile from the samples
1562	    let points: Vec<v2rmp::core::elevation::RouteElevationPoint> = samples_val
1563	        .iter()
1564	        .enumerate()
1565	        .map(|(i, s)| {
1566	            let distance_m = s.get("distance_m").and_then(|v| v.as_f64())
1567	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'distance_m'", i))?;
1568	            let elevation_m = s.get("elevation_m").and_then(|v| v.as_f64())
1569	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'elevation_m'", i))?;
1570	            Ok(v2rmp::core::elevation::RouteElevationPoint {
1571	                distance_m,
1572	                elevation_m: Some(elevation_m),
1573	                point: v2rmp::core::elevation::Point { lon: 0.0, lat: 0.0 },
1574	            })
1575	        })
1576	        .collect::<Result<Vec<_>>>()?;
1577	
1578	    let total_distance_km = points.last().map(|p| p.distance_m / 1000.0).unwrap_or(0.0);
1579	
1580	    let profile = v2rmp::core::elevation::ElevationProfile {
1581	        points,
1582	        total_ascent: 0.0, // Not needed for fuel calc
1583	        total_descent: 0.0,
1584	        max_elevation: 0.0,
1585	        min_elevation: 0.0,
1586	        avg_elevation: 0.0,
1587	        distance_km: total_distance_km,
1588	    };
1589	
1590	    let consumption = FuelCalculator::calculate(&profile, base_consumption);
1591	
1592	    Ok(json!({
1593	        "total_fuel_l": consumption.total_fuel_l,
1594	        "avg_consumption_l_per_km": consumption.avg_consumption_l_per_km,
1595	        "elevation_penalty_l": consumption.elevation_penalty_l,
1596	        "elevation_benefit_l": consumption.elevation_benefit_l,
1597	        "base_consumption_l_per_km": base_consumption,
1598	        "distance_km": total_distance_km,
1599	    }))
1600	}
