1603	
1604	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1605	    let input = args
1606	        .get("input")
1607	        .and_then(|v| v.as_str())
1608	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
1609	
1610	    let file_data = std::fs::read(input)
1611	        .map_err(|e| anyhow::anyhow!("Failed to read .rmp file: {}", e))?;
1612	
1613	    let (nodes, edges) = v2rmp::core::optimize::read_rmp_file(&file_data)?;
1614	
1615	    // Compute bounding box from nodes
1616	    let (min_lon, min_lat, max_lon, max_lat) = if nodes.is_empty() {
1617	        (0.0, 0.0, 0.0, 0.0)
1618	    } else {
1619	        nodes.iter().fold(
1620	            (f64::MAX, f64::MAX, f64::MIN, f64::MIN),
1621	            |(mn_lon, mn_lat, mx_lon, mx_lat), n| {
1622	                (mn_lon.min(n.lon), mn_lat.min(n.lat), mx_lon.max(n.lon), mx_lat.max(n.lat))
1623	            },
1624	        )
1625	    };
1626	
1627	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1628	
1629	    Ok(json!({
1630	        "node_count": nodes.len(),
1631	        "edge_count": edges.len(),
1632	        "bbox": {
1633	            "min_lat": min_lat,
1634	            "max_lat": max_lat,
1635	            "min_lon": min_lon,
1636	            "max_lon": max_lon,
1637	        },
1638	        "total_edge_length_km": total_edge_length_km,
1639	        "file_size_bytes": file_data.len(),
1640	    }))
1641	}
