1877	// ── Pipeline handler ─────────────────────────────────────────────────────
1878	
1879	async fn handle_pipeline(args: &Value) -> Result<Value> {
1880	    let bbox = parse_bbox(args)?;
1881	    let output_dir = args
1882	        .get("output_dir")
1883	        .and_then(|v| v.as_str())
1884	        .unwrap_or("./pipeline-output")
1885	        .to_string();
1886	    let source = match args.get("source").and_then(|v| v.as_str()).unwrap_or("overture") {
1887	        "osm" => ExtractSource::Osm,
1888	        _ => ExtractSource::Overture,
1889	    };
1890	    let pbf_path = args.get("pbf_path").and_then(|v| v.as_str()).map(String::from);
1891	    let depot = args.get("depot").and_then(|d| {
1892	        let lat = d.get("lat")?.as_f64()?;
1893	        let lon = d.get("lon")?.as_f64()?;
1894	        Some((lat, lon))
1895	    });
1896	    let mode = parse_solver_mode(args);
1897	    let prune_disconnected = args.get("prune_disconnected").and_then(|v| v.as_bool()).unwrap_or(false);
1898	
1899	    // Ensure output directory exists
1900	    std::fs::create_dir_all(&output_dir)?;
1901	
1902	    let extract_path = format!("{}/extract.geojson", output_dir);
1903	    let cleaned_path = format!("{}/cleaned.geojson", output_dir);
1904	    let rmp_path = format!("{}/network.rmp", output_dir);
1905	    let route_path = format!("{}/route.gpx", output_dir);
1906	
1907	    // Stage 1: Extract
1908	    tracing::info!("pipeline stage 1: extract");
1909	    let extract_req = ExtractRequest {
1910	        source,
1911	        bbox,
1912	        road_classes: RoadClass::all_vehicle(),
1913	        output_path: extract_path.clone(),
1914	        pbf_path,
1915	    };
1916	    let extract_result = v2rmp::core::extract::run_extract(&extract_req).await?;
1917	
1918	    // Stage 2: Clean
1919	    tracing::info!("pipeline stage 2: clean");
1920	    let input_data = std::fs::read_to_string(&extract_path)?;
1921	    let geojson: geojson::FeatureCollection = serde_json::from_str(&input_data)?;
1922	    let (cleaned, clean_stats, _warnings) = clean_geojson(&geojson, &CleanOptions::default())?;
1923	    let cleaned_str = serde_json::to_string_pretty(&cleaned)?;
1924	    std::fs::write(&cleaned_path, &cleaned_str)?;
1925	
1926	    // Stage 3: Compile
1927	    tracing::info!("pipeline stage 3: compile");
1928	    let compile_req = CompileRequest {
1929	        input_geojson: cleaned_path.clone(),
1930	        output_rmp: rmp_path.clone(),
1931	        compress: false,
1932	        road_classes: vec![],
1933	        clean_options: None,
1934	        prune_disconnected,
1935	    };
1936	    let compile_result = v2rmp::core::compile::run_compile(&compile_req)?;
1937	
1938	    // Stage 4: Optimize
1939	    tracing::info!("pipeline stage 4: optimize");
1940	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1941	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("clarke_wright").to_string();
1942	let optimize_req = OptimizeRequest {
1943	    cache_file: rmp_path.clone(),
1944	    route_file: Some(route_path.clone()),
1945	    turn_penalties: TurnPenalties::default(),
1946	    depot,
1947	    oneway_mode: OnewayMode::default(),
1948	    mode,
1949	    num_vehicles,
1950	    solver_id,
1951	    coordinates: None,
1952	};
1953	    let optimize_result = v2rmp::core::optimize::run_optimize(&optimize_req).await?;
1954	
1955	    Ok(json!({
1956	        "output_dir": output_dir,
1957	        "extract": {
1958	            "nodes": extract_result.nodes,
1959	            "edges": extract_result.edges,
1960	            "total_km": extract_result.total_km,
1961	        },
1962	        "clean": {
1963	            "input_features": clean_stats.input_features,
1964	            "output_features": clean_stats.output_features,
1965	            "total_removed": clean_stats.total_removed(),
1966	        },
1967	        "compile": {
1968	            "node_count": compile_result.node_count,
1969	            "edge_count": compile_result.edge_count,
1970	            "output_size_bytes": compile_result.output_size_bytes,
1971	        },
1972	        "optimize": {
1973	            "total_distance_km": optimize_result.total_distance_km,
1974	            "total_segments": optimize_result.total_segments,
1975	            "deadhead_distance_km": optimize_result.deadhead_distance_km,
1976	            "efficiency_pct": optimize_result.efficiency_pct,
1977	            "num_routes": optimize_result.num_routes,
1978	        },
1979	    }))
1980	}
